#!/bin/bash
#
# DO NOT EDIT THIS FILE but add config options to /etc/default/motd
# any changes will be lost on board support package update
#
export PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin

THIS_SCRIPT="header"
MOTD_DISABLE=""

[[ -f /etc/default/motd ]] && . /etc/default/motd
for f in $MOTD_DISABLE; do
	[[ $f == $THIS_SCRIPT ]] && exit 0
done

. /etc/os-release
. /etc/openwrt_release

KERNELID=$(uname -r)

# if [ $(echo $BOARD_NAME | wc -c) -ge 18 ]; then
	# TERM=linux toilet -f standard -F metal $(echo $BOARD_NAME | sed 's/Orange Pi/OPi/' | sed 's/Nanopi/NPi/')
# else
	# TERM=linux toilet -f standard -F metal S905
# fi

ACCENT='\e[38;5;45m'
MUTED='\e[38;5;244m'
RESET='\e[0m'

printf '\n'
printf "${ACCENT}+----------------------------------------------------------------+${RESET}\n"
printf "${ACCENT}|${RESET} %-62s ${ACCENT}|${RESET}\n" "WayNe OpenWrt :: ${VERSION}"
printf "${ACCENT}|${RESET} %-62s ${ACCENT}|${RESET}\n" "KERNEL ${KERNELID} :: ASCII By @waynesg"
printf "${ACCENT}+----------------------------------------------------------------+${RESET}\n"
printf "${MUTED} boot console initialized / luci shell profile loaded${RESET}\n\n"
